-- ========================================================================
-- NEON POSTGRESQL SCHEMA & INSERTS FOR INDIAN RAILWAYS SMMS MAINTENANCE HISTORY
-- SIH Problem Statement - Signal & Telecom Maintenance Management System (SMMS)
-- Zones: EASTERN RAILWAY (ASN & HWH Divisions), NORTHERN RAILWAY (UMB Division)
-- ========================================================================

CREATE TABLE IF NOT EXISTS smms_maintenance_history (
    job_id VARCHAR(64) PRIMARY KEY,
    source_system VARCHAR(32) NOT NULL DEFAULT 'SMMS_SIGNAL_TELECOM',
    department VARCHAR(32) NOT NULL DEFAULT 'SIGNAL_TELECOM',
    zone VARCHAR(64) NOT NULL,
    zone_code VARCHAR(16) NOT NULL,
    division VARCHAR(32) NOT NULL,
    division_name VARCHAR(64) NOT NULL,
    section VARCHAR(128) NOT NULL,
    section_display VARCHAR(128) NOT NULL,
    block_section VARCHAR(128) NOT NULL,
    block_section_name VARCHAR(128) NOT NULL,
    line VARCHAR(64) NOT NULL,
    work_type VARCHAR(128) NOT NULL,
    asset_type VARCHAR(64) NOT NULL,
    severity VARCHAR(32) NOT NULL,
    criticality VARCHAR(32) NOT NULL,
    overdue_days INTEGER NOT NULL,
    crew_size INTEGER NOT NULL,
    equipment VARCHAR(128) NOT NULL,
    requested_duration_min INTEGER NOT NULL,
    actual_duration_min INTEGER NOT NULL,
    actual_start TIMESTAMP NOT NULL,
    actual_end TIMESTAMP NOT NULL,
    completion_status VARCHAR(64) NOT NULL,
    payload JSONB NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_smms_mh_div ON smms_maintenance_history (division);
CREATE INDEX IF NOT EXISTS idx_smms_mh_zone ON smms_maintenance_history (zone_code);
CREATE INDEX IF NOT EXISTS idx_smms_mh_section ON smms_maintenance_history (section);
CREATE INDEX IF NOT EXISTS idx_smms_mh_bsec ON smms_maintenance_history (block_section);
CREATE INDEX IF NOT EXISTS idx_smms_mh_work ON smms_maintenance_history (work_type);
CREATE INDEX IF NOT EXISTS idx_smms_mh_asset ON smms_maintenance_history (asset_type);
CREATE INDEX IF NOT EXISTS idx_smms_mh_start ON smms_maintenance_history (actual_start);
CREATE INDEX IF NOT EXISTS idx_smms_mh_crit ON smms_maintenance_history (criticality);
CREATE INDEX IF NOT EXISTS idx_smms_mh_payload ON smms_maintenance_history USING gin (payload);

CREATE OR REPLACE VIEW maintenance_history AS SELECT * FROM smms_maintenance_history;

CREATE TABLE IF NOT EXISTS smms_maintenance_feed (
    id SERIAL PRIMARY KEY,
    source_system VARCHAR(32) NOT NULL,
    department VARCHAR(32) NOT NULL,
    record_count INTEGER NOT NULL,
    payload JSONB NOT NULL,
    uploaded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

